"""Every encoder against the bytes the TypeScript ring wrote (`tests/golden_ts.json`, generated by `CommandRing.ts` in `sdk/typescript`)."""
import json
import math
from pathlib import Path

import pytest

from dynova import _wire as w

GOLD = json.loads((Path(__file__).parent / "golden_ts.json").read_text())
GOLD_PARTICLES = json.loads((Path(__file__).parent / "golden_particles_ts.json").read_text())


def hexed(slot: bytes) -> str:
    assert len(slot) == w.SLOT_BYTES
    return slot.hex()


CASES = {
    "spawn": lambda: w.spawn(7, 2, (1.5, -2.25, 3), (0.1, 0.2, 0.3, 0.9), w.SHAPE_SPHERE, (0.4, 0.5, 0.6), 2, 0.25, 0.75, 5),
    "spawn_defaults": lambda: w.spawn(1, 0, (0, 0, 0), (0, 0, 0, 1), w.SHAPE_BOX, (0.5, 0.5, 0.5), 1, 0.3, 0.5, 0),
    "destroy": lambda: w.destroy(9, 3),
    "force": lambda: w.force(4, 1, 1, 2, 3),
    "teleport": lambda: w.teleport(4, 1, -1, 5, 0.5),
    "gravity": lambda: w.gravity(0, -9.81, 0.5),
    "grow": lambda: w.grow(48),
    "record_on": lambda: w.record(True),
    "pause_off": lambda: w.pause(False),
    "seek": lambda: w.seek(1234),
    "checkpoint": w.checkpoint,
    "reset": w.reset,
    "joint_destroy": lambda: w.joint_destroy(11),
    "joint_motor": lambda: w.joint_motor(3, -2.5, 40),
    "joint_hinge": lambda: w.joint_create(7, w.JOINT_HINGE, 3, 1, 9, 2, (1, 2, 3), (0, 0, 1), (-0.5, 0.75), 2, 10),
    "joint_ball_nolimits": lambda: w.joint_create(8, w.JOINT_BALL, 1, 0, 2, 0, (0.5, 0.5, 0.5), (0, 0, 0), None, 0, 0),
}


# The TypeScript `destroy` and `force` leave the unused tail of the slot as it was (the golden slots were pre-filled with 0xff); the runtime ignores
# it, and these encoders zero it, so only the bytes the runtime reads are compared.
PREFIX = {"destroy": 6, "force": 18}


@pytest.mark.parametrize("name", sorted(CASES))
def test_encoder_matches_the_typescript_ring(name):
    ours, theirs = hexed(CASES[name]()), GOLD[name]
    cut = PREFIX.get(name, w.SLOT_BYTES) * 2
    assert ours[:cut] == theirs[:cut]
    if name in PREFIX:
        assert ours[cut:] == "00" * (w.SLOT_BYTES - cut // 2)


def test_every_golden_slot_is_covered():
    assert set(CASES) == {k for k in GOLD if k != "run_bits"}


def test_tags_are_the_values_the_runtime_pins():
    assert [w.TAG_SPAWN, w.TAG_DESTROY, w.TAG_FORCE, w.TAG_GROW, w.TAG_GRAVITY] == [0, 1, 2, 3, 4]
    assert [w.TAG_TELEPORT, w.TAG_RECORD, w.TAG_SEEK, w.TAG_PAUSE] == [8, 9, 10, 11]
    assert [w.TAG_JOINT_CREATE, w.TAG_JOINT_DESTROY, w.TAG_JOINT_MOTOR, w.TAG_CHECKPOINT, w.TAG_RESET] == [12, 13, 14, 18, 19]
    assert [w.TAG_PARTICLE_CHAIN, w.TAG_PARTICLE_CLOTH, w.TAG_PARTICLE_ATTACH, w.TAG_PARTICLE_DETACH, w.TAG_PARTICLE_SOFT] == [20, 21, 22, 23, 24]
    assert (w.H_PSTATE_SEQ, w.H_PSTATE_ROWS, w.H_PSTATE_N, w.HEADER_WORDS) == (41, 42, 43, 44)


def test_a_value_beyond_f32_is_an_error_not_a_silent_infinity():
    with pytest.raises(OverflowError):
        w.force(0, 0, 1e39, 0, 0)


def test_floats_round_to_f32_like_math_fround():
    slot = w.teleport(0, 0, 0.1, 0.2, 1 / 3)
    import struct
    x, y, z = struct.unpack_from("<3f", slot, 6)
    assert (x, y, z) == (struct.unpack("<f", struct.pack("<f", 0.1))[0], struct.unpack("<f", struct.pack("<f", 0.2))[0], struct.unpack("<f", struct.pack("<f", 1 / 3))[0])
    assert not math.isclose(x, 0.1, rel_tol=0, abs_tol=1e-12)


PARTICLE_CASES = {
    "chain": lambda: w.particle_chain(70000, (1, 2, 3), (-1, 2, 3.5), 300, True, True, 0.025, 2, 0.75),
    "cloth": lambda: w.particle_cloth(70000, (1, 2, 3), (2, 0, 0.5), (0, 0, 3), 64, 17, 22, 0.04, 2, 0.75, 0.25),
    "soft": lambda: w.particle_soft(70000, (1, 2, 3), (0.5, 1, 2), (4, 12, 2), 0.1, 2, 0.75),
    "attach": lambda: w.particle_attach(70000, 123456, 9, (0.5, -1, 2)),
    "detach": lambda: w.particle_detach(5),
}


@pytest.mark.parametrize("name", sorted(PARTICLE_CASES))
def test_particle_encoders_write_the_bytes_the_typescript_ring_wrote(name):
    assert hexed(PARTICLE_CASES[name]()) == GOLD_PARTICLES[name]


def test_the_particle_golden_has_exactly_these_cases():
    assert set(PARTICLE_CASES) == set(GOLD_PARTICLES)
